function r(e){switch(e){case"Open":return{label:"To do",tone:"neutral",says:"Nobody has this yet."};case"Released":return{label:"Released",tone:"blue",says:"Ready for whoever takes it."};case"Moving":return{label:"On its way",tone:"blue",says:"A robot has it. The stock stays where it was until someone confirms it."};case"Arrived":return{label:"Arrived",tone:"amber",says:"The robot says it is there. Scan the destination: nothing has moved until you do."};case"Exception":return{label:"Needs someone",tone:"red",says:"Nobody can say where this is. Find it, then say where."};case"Short":return{label:"Short",tone:"amber",says:"Less moved than was asked."};case"Done":return{label:"Done",tone:"green",says:"Moved and confirmed."};default:return{label:e,tone:"neutral",says:""}}}function a(e){return e==="In Transit"?"On its way, and still counted at its source":e==="Uncertain"?"Nobody can say where this is. It stays out of reach until someone finds it":null}function o(e){const t=s=>["Exception","Arrived","Released","Open","Moving"].indexOf(s.status);return[...e].sort((s,n)=>t(s)-t(n))}const i=e=>e.trim();function u(e,t){return Number(t)<Number(e)}function c(e){const t=Number(e.received_qty??0)+Number(e.damaged_qty??0),s=Number(e.expected_qty);return{got:t,left:Math.max(s-t,0),over:t>s}}const d=e=>e.filter(t=>Number(t.verified_qty??0)<Number(t.qty));export{i as a,o as b,a as c,c as l,u as s,r as t,d as u};
